create or replace function public.dateme_can_video_call(p_match_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.matches m join public.member_subscriptions mine on mine.user_id=auth.uid() join public.member_subscriptions theirs on theirs.user_id=case when m.user_one=auth.uid() then m.user_two else m.user_one end where m.id=p_match_id and auth.uid() in(m.user_one,m.user_two) and mine.plan_code='yearly' and theirs.plan_code='yearly' and mine.status='active' and theirs.status='active' and mine.payment_verified=true and theirs.payment_verified=true and mine.ends_at is not null and theirs.ends_at is not null and mine.ends_at>now() and theirs.ends_at>now()) $$; revoke execute on function public.dateme_can_video_call(uuid) from anon,public; grant execute on function public.dateme_can_video_call(uuid) to authenticated; drop policy if exists call_signals_read_participants on public.member_call_signals; create policy call_signals_read_participants on public.member_call_signals for select to authenticated using(auth.uid() in(sender_id,recipient_id) and exists(select 1 from public.matches m where m.id=match_id and auth.uid() in(m.user_one,m.user_two)) and public.dateme_can_video_call(match_id)); drop policy if exists call_signals_insert_sender on public.member_call_signals; create policy call_signals_insert_sender on public.member_call_signals for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.matches m where m.id=match_id and auth.uid() in(m.user_one,m.user_two) and recipient_id in(m.user_one,m.user_two)) and public.dateme_can_video_call(match_id));